"""Original application-authored items; Python 3 and portable SQL semantics."""


def _question(position, prompt, choices, answer, explanation):
    return {
        "position": position, "question_text": prompt,
        "options": [dict(key=key, text=text) for key, text in zip("ABCD", choices)],
        "correct_option": answer, "explanation": explanation,
    }


PYTHON_QUESTIONS = [
    _question(1, "In Python 3, what is the value of 7 // 2?",
              ["3.5", "3", "4", "1"], "B",
              "// performs floor division. For these positive integers, 7 // 2 is 3."),
    _question(2, "What is printed?\nvalues = [2, 4]\nother = values\nother.append(6)\nprint(values)",
              ["[2, 4]", "[6]", "[2, 4, 6]", "An error is raised"], "C",
              "Assignment binds both names to the same mutable list; append changes that list."),
    _question(3, "What is the value of list(range(1, 6, 2))?",
              ["[1, 3, 5]", "[1, 3, 5, 6]", "[2, 4, 6]", "[1, 2, 3, 4, 5]"], "A",
              "range starts at 1, advances by 2, and excludes the stop value 6."),
    _question(4, "Given scores = {'Ada': 8}, which expression returns 0 for a missing 'Lin' key without inserting it?",
              ["scores['Lin']", "scores.pop('Ada')", "scores.setdefault('Lin', 0)", "scores.get('Lin', 0)"], "D",
              "get returns its default for a missing key without modifying the dictionary; setdefault inserts it."),
    _question(5, "What does this function return when called as label(3)?\ndef label(n):\n    if n > 0:\n        return 'positive'\n    return 'other'",
              ["'other'", "'positive'", "None", "True"], "B",
              "The condition is true, so return immediately exits the function with 'positive'."),
    _question(6, "Which exception should be caught specifically when int('three') cannot parse the string?",
              ["KeyError", "IndexError", "ValueError", "FileNotFoundError"], "C",
              "The string is an accepted input type for int, but its value is not a valid integer representation."),
    _question(7, "What is [n * n for n in [1, 2, 3, 4] if n % 2 == 0]?",
              ["[4, 16]", "[1, 9]", "[2, 4]", "[1, 4, 9, 16]"], "A",
              "The condition selects 2 and 4; the expression squares each selected number."),
    _question(8, "Why is 'with open(path, encoding=\"utf-8\") as handle:' useful when reading a text file?",
              ["It guarantees that the path exists", "It loads every line into memory immediately", "It suppresses all read errors", "It closes the file when the block exits, including on an exception"], "D",
              "The file context manager closes the handle on block exit. Opening or reading may still raise errors."),
    _question(9, "Which definition gives each call without an argument a fresh list?",
              ["def collect(items=[]):\n    return items", "def collect(items=None):\n    if items is None:\n        items = []\n    return items", "shared = []\ndef collect(items=shared):\n    return items", "def collect(items=list()):\n    return items"], "B",
              "Defaults are evaluated once at function definition. Using None and constructing a list inside creates a fresh list per omitted argument."),
    _question(10, "Given names = ['Ada', 'Lin', 'Sam', 'Jo'], what is names[1:3]?",
              ["['Ada', 'Lin', 'Sam']", "['Lin', 'Sam', 'Jo']", "['Lin', 'Sam']", "['Ada', 'Lin']"], "C",
              "Slicing uses zero-based indexes and excludes the end index: positions 1 and 2 are selected."),
]

SQL_QUESTIONS = [
    _question(1, "A products table has columns name and price. Which query returns only names of products priced above 20?",
              ["SELECT name FROM products WHERE price > 20;", "SELECT price FROM products WHERE name > 20;", "SELECT name FROM products HAVING name > 20;", "SELECT name FROM products ORDER BY price > 20;"], "A",
              "SELECT chooses the output column; WHERE filters individual rows using price."),
    _question(2, "Which predicate selects rows whose shipped_at value is NULL?",
              ["shipped_at = NULL", "shipped_at <> NULL", "shipped_at = 'NULL'", "shipped_at IS NULL"], "D",
              "IS NULL tests for a missing value. Ordinary comparisons to NULL evaluate to unknown, not true."),
    _question(3, "An orders table has three rows; amount contains 10, NULL, and 20. What does SELECT COUNT(*), COUNT(amount) FROM orders return?",
              ["2, 2", "3, 2", "3, 3", "2, 3"], "B",
              "COUNT(*) counts all rows, while COUNT(amount) excludes NULL amounts."),
    _question(4, "Which query returns customer IDs having at least three orders?",
              ["SELECT customer_id FROM orders WHERE COUNT(*) >= 3;", "SELECT customer_id FROM orders GROUP BY customer_id WHERE COUNT(*) >= 3;", "SELECT customer_id FROM orders GROUP BY customer_id HAVING COUNT(*) >= 3;", "SELECT customer_id FROM orders HAVING customer_id >= 3;"], "C",
              "GROUP BY forms a group per customer and HAVING filters those groups by their count."),
    _question(5, "Customers has one row for each id 1 and 2. Orders has two rows for customer_id 1 and none for 2. How many rows does SELECT c.id, o.id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id return?",
              ["3", "2", "1", "0"], "A",
              "Customer 1 produces two matching rows. The left join also preserves customer 2 with NULL order columns."),
    _question(6, "Which clause sorts employees by salary highest first, then by unique employee_id lowest first to break ties?",
              ["ORDER BY salary ASC, employee_id DESC", "GROUP BY salary DESC, employee_id ASC", "ORDER BY employee_id ASC, salary DESC", "ORDER BY salary DESC, employee_id ASC"], "D",
              "Sort expressions apply left to right. DESC puts larger salaries first; the unique ID gives deterministic tie ordering."),
    _question(7, "Which statement about a primary key is correct?",
              ["Its values must be consecutive integers", "It uniquely identifies each row and its columns cannot be NULL", "It automatically sorts every SELECT result", "It allows duplicate values when other columns differ"], "B",
              "A primary key enforces uniqueness and non-NULL key columns; it does not promise numbering or query ordering."),
    _question(8, "Which statement changes only orders currently marked 'pending' to 'ready'?",
              ["UPDATE orders SET status = 'ready';", "UPDATE orders WHERE status = 'pending' SET status = 'ready';", "UPDATE orders SET status = 'ready' WHERE status = 'pending';", "SELECT status = 'ready' FROM orders WHERE status = 'pending';"], "C",
              "UPDATE assigns new values and WHERE limits the affected rows. Omitting WHERE would update every row."),
    _question(9, "In a transactional database, two balance updates form one transfer inside an explicit transaction. The second fails before commit. What should the application do to avoid keeping just the first update?",
              ["Roll back the transaction", "Commit the first update", "Run SELECT DISTINCT", "Create an index"], "A",
              "Rolling back abandons the transaction's uncommitted changes, preserving the all-or-nothing transfer."),
    _question(10, "An application searches by a user-entered email. Which approach keeps that value from being interpreted as SQL syntax?",
              ["Concatenate the email into a quoted SQL string", "Remove spaces from the email", "Convert the email to lowercase before concatenation", "Use a parameterized query and bind the email as a value"], "D",
              "Bound parameters separate data values from SQL syntax. Formatting or simple string filtering does not provide that separation."),
]
